changeSet.sql:
-- Schema usage GRANT USAGE ON SCHEMA nexus TO nexus_svc; GRANT USAGE ON SCHEMA t1 TO nexus_svc;
DO $$ DECLARE rel RECORD; skipped_count integer; skipped_names text; BEGIN -- DML + sequence usage on every relation THIS role owns (nexus_admin -- created the schema, so this covers every table/view/sequence in -- normal operation). Foreign-owned relations (e.g. the superuser-owned -- diag_chash_conformance view) are skipped by construction — nexus_svc -- does not need them. FOR rel IN SELECT n.nspname, c.relname, c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('nexus', 't1') AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S') AND pg_get_userbyid(c.relowner) = current_user LOOP IF rel.relkind = 'S' THEN EXECUTE format( 'GRANT USAGE, SELECT ON %I.%I TO nexus_svc', rel.nspname, rel.relname ); ELSE EXECUTE format( 'GRANT SELECT, INSERT, UPDATE, DELETE ON %I.%I TO nexus_svc', rel.nspname, rel.relname ); END IF; END LOOP;
-- Operator visibility (review finding): a foreign-owned relation is -- skipped BY DESIGN — only its owner can grant on it, and nexus_svc does -- not need the diag view today. But a deployment that ever drifts from -- the nexus_admin-owns-everything contract (e.g. a future -- superuser-provisioned object nexus_svc DOES need) would otherwise fail -- silently at first query instead of visibly at boot. NOTICE, not -- WARNING: skip is by design, not an error. SELECT count(*), string_agg(n.nspname || '.' || c.relname, ', ') INTO skipped_count, skipped_names FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('nexus', 't1') AND c.relkind IN ('r', 'p', 'v', 'm', 'f', 'S') AND pg_get_userbyid(c.relowner) != current_user;
IF skipped_count > 0 THEN RAISE NOTICE 'grants-nexus-svc-1: skipped % foreign-owned relation(s), not granted to nexus_svc (only their owner can grant): %', skipped_count, skipped_names; END IF; END $$;
-- MAINTAIN on chash_alias (rdr180-17 / F2, production 2026-07-20) — RETIRED -- at nexus-lgdel.l1: nexus.chash_alias is DROPPED (legacy-001-drop-chash- -- alias.xml), and its only two callers (RekeyOps.rekey, StagingPromoteOps. -- promoteCollection's refreshAliasStats call) are deleted in that same -- commit. Editing this runAlways changeset's body is checksum-safe -- (ValidatingVisitor skips the MD5SUM comparison for shouldAlwaysRun() — -- see grants-003-purge-vacuum-maintain's comment for the identical -- precedent). This grant is removed outright rather than guarded, unlike -- grants-003's early-return pattern: that guard exists for a table that is -- CONDITIONALLY present depending on unify-migration state; chash_alias has -- no such conditional existence going forward, so there is nothing left to -- guard for.
-- Default privileges: future tables/sequences created by the schema owner automatically -- carry the same grants for nexus_svc (self-healing for new migrations). ALTER DEFAULT PRIVILEGES IN SCHEMA nexus GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nexus_svc; ALTER DEFAULT PRIVILEGES IN SCHEMA nexus GRANT USAGE, SELECT ON SEQUENCES TO nexus_svc; ALTER DEFAULT PRIVILEGES IN SCHEMA t1 GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nexus_svc; ALTER DEFAULT PRIVILEGES IN SCHEMA t1 GRANT USAGE, SELECT ON SEQUENCES TO nexus_svc;

DO $$
BEGIN
    -- RDR-191 era guard (see changeset comment): post-unify the per-dim
    -- tables are gone and grants-005 owns MAINTAIN. Body guard, not
    -- preConditions MARK_RAN (nexus-ixsxa).
    IF to_regclass('nexus.chunks_384') IS NULL THEN
        RETURN;
    END IF;
    IF current_setting('server_version_num')::int >= 170000 THEN
        EXECUTE 'GRANT MAINTAIN ON nexus.chunks_384 TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.chunks_768 TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.chunks_1024 TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.catalog_document_chunks TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.catalog_documents TO nexus_svc';
    ELSE
        RAISE NOTICE 'grants-nexus-svc: server % predates MAINTAIN (PG17+); purge-trash post-commit VACUUM (nexus-0ys55) will schedule but silently permission-skip every table for every purge-trash execute call on this substrate until it is upgraded -- see the vacuum executor completion log, not the HTTP response, for the skip detail.',
            current_setting('server_version');
    END IF;
END
$$;

DO $$
BEGIN
    BEGIN
        GRANT pg_monitor TO nexus_svc;
    EXCEPTION WHEN insufficient_privilege THEN
        RAISE EXCEPTION 'grants-004-monitor-wal-visibility: nexus_admin lacks ADMIN OPTION on pg_monitor, so it cannot grant pg_monitor onward to nexus_svc. REMEDY: as a PostgreSQL superuser, run: GRANT pg_monitor TO nexus_admin WITH ADMIN OPTION; -- the local bundle installer does this automatically (src/nexus/db/pg_provision.py); bring-your-own/managed Postgres deployments must run it manually per docs/configuration.md prerequisite 2. Original error: %', SQLERRM;
    END;
END
$$;

DO $$
BEGIN
    IF current_setting('server_version_num')::int >= 170000 THEN
        EXECUTE 'GRANT MAINTAIN ON nexus.chunks TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.catalog_document_chunks TO nexus_svc';
        EXECUTE 'GRANT MAINTAIN ON nexus.catalog_documents TO nexus_svc';
    ELSE
        RAISE NOTICE 'grants-005-chunks-unify-maintain: server % predates MAINTAIN (PG17+)', current_setting('server_version');
    END IF;
END
$$;
